const raw = $json.output;

// 1. parse JSON
const data = JSON.parse(raw);

// 2. summary
const summary = (data.summary || '').replace(/\n/g, ' ').trim();

// helper
const asArray = (v) => Array.isArray(v) ? v : (v ? [v] : []);

// 3. priority mapping (Jira-friendly)
const priorityMap = {
  highest: "1",
  high: "2",
  medium: "3",
  low: "4",
  lowest: "5"
};

const priorityRaw = (data.priority || '').toLowerCase();
const priority_id = priorityMap[priorityRaw] || "3";

// 4. arrays
const preconditions = asArray(data.preconditions);
const steps = asArray(data.steps_to_reproduce);
const actual = asArray(data.actual_result);
const expected = asArray(data.expected_result);

// 5. block formatter
const block = (title, value) =>
`${title}:\n${value}`;

// 6. description (как у тебя было)
const description =
`${block('REPORTER', data.reporter || '-')}

${block('TYPE', data.type || '-')}

${block('DESCRIPTION', data.description || '-')}

${block('ENVIRONMENT', data.environment || '-')}

${block('PRECONDITIONS', preconditions.length ? preconditions.join('\n') : '-')}

${block('STEPS TO REPRODUCE', steps.length ? steps.map((s, i) => `${i + 1}. ${s}`).join('\n') : '-')}

${block('ACTUAL RESULT', actual.length ? actual.join('\n') : '-')}

${block('EXPECTED RESULT', expected.length ? expected.join('\n') : '-')}

${block('PRIORITY', data.priority || '-')}

${block('SEVERITY', data.severity || '-')}

${block('ADDITIONAL', data.additional || '-')}`.trim();

// 7. return
return [
  {
    json: {
      summary,
      description,
      priority: data.priority || '-',
      priority_id
    }
  }
];

